"""
NATS JetStream message queue infrastructure generator for AetherOS Layer 5.

Generates NATS Helm values, stream configs, async Python client, and docker-compose
blocks as files inside a generated project's output directory.
"""
from __future__ import annotations

import logging
from pathlib import Path
from typing import List

logger = logging.getLogger(__name__)


def generate_nats_helm_values(slug: str) -> str:
    """NATS Helm values: 3 replicas, JetStream enabled, memory+file storage, TLS config."""
    return f"""\
## NATS JetStream Helm values — generated by AetherOS for {slug}
nats:
  cluster:
    enabled: true
    replicas: 3
    name: {slug}-cluster
  jetstream:
    enabled: true
    memStorage:
      enabled: true
      size: 1Gi
    fileStorage:
      enabled: true
      size: 10Gi
      storageDirectory: /data/jetstream
      storageClass: "standard"
  nats:
    resources:
      requests:
        memory: "256Mi"
        cpu: "100m"
      limits:
        memory: "1Gi"
        cpu: "500m"
  tls:
    enabled: true
    secretName: {slug}-nats-tls
  auth:
    enabled: true
    secretName: {slug}-nats-auth
  exporter:
    enabled: true
    serviceMonitor:
      enabled: true
      additionalLabels:
        release: prometheus
"""


def generate_stream_config(entity_name: str, slug: str) -> str:
    """
    NATS stream YAML for a single entity.

    One stream per entity (retention=limits, max_msgs=1_000_000, replicas=3).
    Also includes a dead-letter stream for failed processing.
    """
    stream_name = f"{slug.upper()}_{entity_name.upper()}"
    dlq_name = f"{stream_name}_DLQ"
    subjects = f"{slug}.{entity_name}.>"

    return f"""\
## NATS JetStream stream config for entity: {entity_name} — generated by AetherOS
streams:
  - name: {stream_name}
    subjects:
      - "{subjects}"
    retention: limits
    max_msgs: 1000000
    max_bytes: -1
    max_age: 72h
    max_msg_size: 1048576  # 1 MiB
    num_replicas: 3
    storage: file
    discard: old
    duplicate_window: 2m
    consumers:
      - name: {entity_name}-worker
        durable_name: {entity_name}-worker
        filter_subject: "{subjects}"
        ack_policy: explicit
        ack_wait: 30s
        max_deliver: 5
        deliver_policy: all

  # Dead-letter stream — the generated client publishes a message here on its last failed delivery
  # (JetStream itself only stops redelivering, the message would be lost)
  - name: {dlq_name}
    subjects:
      - "{slug}.dlq.{entity_name}.>"   # outside "{slug}.{entity_name}.>": JetStream refuses overlapping streams
    retention: limits
    max_msgs: 100000
    max_bytes: -1
    max_age: 720h  # 30 days retention for DLQ inspection
    num_replicas: 3
    storage: file
    discard: old
"""


def generate_python_queue_client(entities: List[dict]) -> str:
    """Async Python NATS client: publish, subscribe, ack/nak per entity."""

    return """\
\"\"\"
Async NATS JetStream queue client — generated by AetherOS.
Provides publish/subscribe with ack/nak support per domain entity.
\"\"\"
from __future__ import annotations

import asyncio
import json
import logging
import os
from typing import Any, Awaitable, Callable, Dict, Optional

import nats
from nats.aio.client import Client as NATSClient
from nats.js import JetStreamContext
from nats.js.api import AckPolicy, ConsumerConfig

logger = logging.getLogger(__name__)

_SLUG = os.environ.get("APP_SLUG", "app")
_MAX_DELIVER = 5   # the same limit as the stream definition (max_deliver)

# Subject pattern: {slug}.{entity}.{event_type}
_SUBJECTS: Dict[str, str] = {
""" + "\n".join(
        f'    "{e.get("table", "item")}": f"{{_SLUG}}.{e.get("table", "item")}.{{{{event_type}}}}",'
        for e in entities
    ) + """
}


class QueueClient:
    \"\"\"Async NATS JetStream client for AetherOS-generated apps.\"\"\"

    def __init__(self) -> None:
        self._nc: Optional[NATSClient] = None
        self._js: Optional[JetStreamContext] = None
        self._url = os.environ.get("NATS_URL", "nats://nats:4222")

    async def connect(self) -> None:
        \"\"\"Connect to NATS server and get JetStream context.\"\"\"
        try:
            self._nc = await nats.connect(
                self._url,
                user=os.environ.get("NATS_USER", ""),
                password=os.environ.get("NATS_PASSWORD", ""),
                reconnect_time_wait=2,
                max_reconnect_attempts=5,
            )
            self._js = self._nc.jetstream()
            logger.info("queue: connected to NATS at %s", self._url)
        except Exception as e:
            logger.warning("queue: NATS connect failed: %s", e)
            raise

    async def disconnect(self) -> None:
        \"\"\"Drain and close the NATS connection.\"\"\"
        if self._nc:
            try:
                await self._nc.drain()
            except Exception as e:
                logger.warning("queue: drain error on disconnect: %s", e)

    async def publish(self, entity: str, event_type: str, payload: Dict[str, Any]) -> None:
        \"\"\"Publish an event for the given entity. payload is JSON-serialized.\"\"\"
        if self._js is None:
            raise RuntimeError("QueueClient not connected — call connect() first")
        subject_tpl = _SUBJECTS.get(entity)
        if subject_tpl is None:
            raise ValueError(f"Unknown entity: {entity}")
        subject = subject_tpl.format(event_type=event_type)
        data = json.dumps(payload).encode()
        try:
            ack = await self._js.publish(subject, data)
            logger.info("queue: published to %s seq=%s", subject, ack.seq)
        except Exception as e:
            logger.warning("queue: publish failed subject=%s: %s", subject, e)
            raise

    async def subscribe(
        self,
        entity: str,
        event_type: str,
        handler: Callable[[Dict[str, Any]], Awaitable[None]],
    ) -> None:
        \"\"\"Subscribe to events for entity+event_type. Calls handler with parsed payload.\"\"\"
        if self._js is None:
            raise RuntimeError("QueueClient not connected — call connect() first")
        subject_tpl = _SUBJECTS.get(entity)
        if subject_tpl is None:
            raise ValueError(f"Unknown entity: {entity}")
        subject = subject_tpl.format(event_type=event_type)
        durable = f"{entity}-{event_type}-worker"

        async def _msg_handler(msg: Any) -> None:
            try:
                payload = json.loads(msg.data.decode())
                await handler(payload)
                await msg.ack()
            except Exception as e:
                delivered = msg.metadata.num_delivered
                if delivered >= _MAX_DELIVER:
                    # JetStream only stops redelivering: park the message in the dead-letter stream.
                    logger.error("queue: giving up on %s after %d deliveries: %s", subject, delivered, e)
                    try:
                        await self._js.publish(f"{_SLUG}.dlq.{entity}.{event_type}", msg.data,
                                               headers={"error": str(e)[:200], "subject": subject})
                        await msg.term()
                    except Exception as dlq_exc:
                        logger.error("queue: dead-letter publish failed, message stays unacked: %s", dlq_exc)
                else:
                    logger.warning("queue: handler error subject=%s delivery=%d: %s", subject, delivered, e)
                    await msg.nak(delay=min(2 ** delivered, 60))   # back off: an immediate nak is a hot loop

        try:
            await self._js.subscribe(
                subject, durable=durable, cb=_msg_handler, manual_ack=True,
                config=ConsumerConfig(max_deliver=_MAX_DELIVER, ack_wait=30, ack_policy=AckPolicy.EXPLICIT),
            )
            logger.info("queue: subscribed to %s (durable=%s)", subject, durable)
        except Exception as e:
            logger.warning("queue: subscribe failed subject=%s: %s", subject, e)
            raise


# Module-level singleton for convenience
_client: Optional[QueueClient] = None


async def get_queue_client() -> QueueClient:
    \"\"\"Return connected singleton QueueClient.\"\"\"
    global _client
    if _client is None:
        _client = QueueClient()
        await _client.connect()
    return _client
"""


def generate_nats_docker_compose(slug: str) -> str:
    """docker-compose block for NATS JetStream single-node."""
    return f"""\
  # NATS JetStream message queue — generated by AetherOS for {slug}
  nats:
    image: nats:2.10-alpine
    # Credentials come from the environment (a .env file or the shell) through compose
    # interpolation, never from this file. NATS_USER / NATS_PASSWORD are the same variables the
    # generated client reads; compose refuses to start without them and the ports are published
    # on localhost only.
    environment:
      NATS_USER: ${{NATS_USER:?set NATS_USER}}
      NATS_PASSWORD: ${{NATS_PASSWORD:?set NATS_PASSWORD}}
    command: >
      -js
      -m 8222
      -p 4222
      --user ${{NATS_USER}}
      --pass ${{NATS_PASSWORD}}
    ports:
      - "127.0.0.1:4222:4222"
      - "127.0.0.1:8222:8222"
    volumes:
      - nats_data:/data
    healthcheck:
      test: ["CMD", "wget", "-q", "--spider", "http://localhost:8222/healthz"]
      interval: 15s
      timeout: 5s
      retries: 3
    networks:
      - {slug}_network

volumes:
  nats_data:
"""


def generate_queue_package(
    entities: List[dict],
    slug: str,
    output_dir: Path,
    deployment_target: str,
) -> Path:
    """
    Writes all NATS queue files to output_dir/queue/ and returns the directory.
    """
    queue_dir = output_dir / "queue"
    queue_dir.mkdir(parents=True, exist_ok=True)

    # Helm values for Kubernetes deployments
    (queue_dir / "nats-values.yaml").write_text(generate_nats_helm_values(slug))

    # Per-entity stream config
    streams_dir = queue_dir / "streams"
    streams_dir.mkdir(exist_ok=True)
    for entity in entities:
        table = entity.get("table", "item")
        (streams_dir / f"{table}-stream.yaml").write_text(
            generate_stream_config(table, slug)
        )

    # Python async client
    (queue_dir / "queue_client.py").write_text(generate_python_queue_client(entities))

    # Docker Compose block
    (queue_dir / "docker-compose.queue.yml").write_text(
        generate_nats_docker_compose(slug)
    )

    logger.info(
        "queue: generated %d stream configs at %s (target=%s)",
        len(entities),
        queue_dir,
        deployment_target,
    )
    return queue_dir
